mapper.codeEditorJavascript:
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const titles=(input.sheets||[]).map(s=>String((s.properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(let k=0;k<2;k++){const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+k,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(d>=new Date(2026,9,1) && titles.includes(t)) tabs.push(t);}
return {count:tabs.length, body: JSON.stringify({dataFilters: tabs.map(t=>({a1Range:"'"+t+"'!A1:T2000"})).concat([{a1Range:"'בקשות להקדמה'!A1:O5000"}]), valueRenderOption:'FORMATTED_VALUE'})};

const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const DAYS=['יום ראשון','יום שני','יום שלישי','יום רביעי','יום חמישי','יום שישי','יום שבת'];
// today in Israel
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const today=new Date(nowIL.getFullYear(),nowIL.getMonth(),nowIL.getDate());
function parseHeb(s){
  s=String(s||'');
  const m=s.match(/(\d{1,2})\s+(\S+)\s+(\d{4})/);
  if(m){const mi=MONTHS.indexOf(m[2]); if(mi>=0) return new Date(+m[3],mi,+m[1]);}
  const n=s.match(/(\d{1,2})[\/.](\d{1,2})[\/.](\d{2,4})/);
  if(n){let y=+n[3]; if(y<100)y+=2000; return new Date(y,+n[2]-1,+n[1]);}
  return null;
}
function workdaysAhead(d){ // Sun-Thu days from tomorrow through d inclusive
  let c=0; const x=new Date(today);
  while(true){x.setDate(x.getDate()+1); if(x>d) break; const w=x.getDay(); if(w<=4) c++; if(c>60) break;}
  return c;
}
const all=input.ranges||[];
const isReq=vr=>String((vr.valueRange||{}).range||'').includes('בקשות להקדמה');
const reqVr=all.find(isReq);
const ranges=all.filter(vr=>!isReq(vr));
const existing=(reqVr&&reqVr.valueRange&&reqVr.valueRange.values)||[];
const old=(input.old||[]).filter(r=>String(r[6]||'').trim()==='כן');
const seenCust=new Set(), seenPhone=new Set();
const digits=v=>String(v||'').replace(/\D/g,'').replace(/^972/,'0');
for(const r of existing.concat(old)){ if(r[9]) seenCust.add(String(r[9]).trim()); if(r[2]) seenPhone.add(digits(r[2])); }
let num=0; for(const r of existing){const a=parseInt(r[0],10); if(!isNaN(a)&&a>num) num=a;}
const out=[]; const skipped={short:0,recentSale:0,dup:0,noPhone:0,notSigned:0,bezeq:0,infra:0};
const todayTxt=today.getDate()+'/'+(today.getMonth()+1)+'/'+today.getFullYear();
const minSale=new Date(today); minSale.setDate(minSale.getDate()-2);
for(const vr of ranges){
  const vals=(vr.valueRange&&vr.valueRange.values)||[];
  if(!vals.length) continue;
  const h=vals[0].map(x=>String(x||'').trim());
  const ix=name=>h.findIndex(x=>x.startsWith(name));
  const tabName=String((vr.valueRange||{}).range||'').split('!')[0].replace(/'/g,'');
  const iSale=ix('תאריך מכירה'), iName=ix('שם לקוח'), iPhone=ix('נייד'), iInst=ix('תאריך התקנה'), iTime=ix('שעת התקנה'), iCust=ix('מספר לקוח'), iRep=ix('נציג מוכר'), iNote=ix('הערות'), iWhat=ix('מה נמכר'), iInfra=ix('תשתיות');
  for(const r of vals.slice(1)){
    const inst=parseHeb(r[iInst]); if(!inst) continue;
    const what=String(iWhat>=0?(r[iWhat]||''):'');
    if(what.includes('בזק')){skipped.bezeq++; continue;}
    const sale=parseHeb(r[iSale]);
    const cust=String(r[iCust]||'').trim();
    const ph=digits(r[iPhone]);
    if(!ph){skipped.noPhone++; continue;}
    const note=String(iNote>=0?(r[iNote]||''):'');
    if(note.includes('בוטל')){skipped.notSigned++; continue;}
    const infraMarked=iInfra>=0 && String(r[iInfra]||'').trim()==='כן';
    if(infraMarked||note.includes('תשתיות')){skipped.infra++; continue;}
    const wd=workdaysAhead(inst);
    if(wd<5){skipped.short++; continue;}
    if(!sale||sale>minSale){skipped.recentSale++; continue;}
    if((cust&&seenCust.has(cust))||seenPhone.has(ph)){skipped.dup++; continue;}
    seenPhone.add(ph); if(cust) seenCust.add(cust);
    const instTxt=DAYS[inst.getDay()]+' '+inst.getDate()+' '+MONTHS[inst.getMonth()]+' '+inst.getFullYear();
    num++;
    out.push([num,String(r[iName]||'').trim(),String(r[iPhone]||'').trim(),instTxt,String(r[iTime]||'').trim(),String(r[iRep]||'').trim(),(/^05\d{8}$/.test(ph)?'':'מספר לא תקין'),'','',cust,String(r[iSale]||'').trim(),wd,tabName,todayTxt]);
  }
}
const startRow=Math.max(existing.length,1)+1;
return {count:out.length, skipped:JSON.stringify(skipped), body:JSON.stringify({valueInputOption:'RAW',data:[{range:"'בקשות להקדמה'!A"+startRow,values:out}]})};
